Let $\psi:\mathbb{N}\rightarrow \mathbb{R}_{\geqslant 0}$ be a function such that
\[
\sum_{q=1}^\infty \frac{\psi(q)\varphi(q)}{q}=\infty.
\]
Let $\mathcal{A}$ be the set of $\alpha\in[0,1]$ for which the inequality
\begin{equation} \begin{split} 

\bigg|\alpha-\frac{a}{q}\bigg| \leqslant \frac{\psi(q)}{q}
 \end{split} \end{equation}
has infinitely many coprime solutions $a$ and $q$. 
Then $\mathcal{A}$ has Lebesgue measure 1.

Let $G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\emptyset,f_\emptyset,g_\emptyset)$ be a GCD graph with trivial set of primes and edge density $\delta>0$. Assume further that
\[
\mathcal{E}\subseteq\{(v,w)\in\mathbb{N}^2 :  L_t(v,w) \geqslant10\}
\]
for some $t$ satisfying 
\[
t\geqslant10\delta^{-1/50}\quad\text{and}\quad t> 10^{2000}.
\]
Then there is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P}',f',g')$ of $G$ with edge density $\delta'>0$ such that:
\begin{enumerate}[label=(\alph*)]
\item  $\mathcal{R}(G')=\emptyset$;
\item For all $v\in\mathcal{V}'$, we have $\mu(\Gamma_{G'}(v))\geqslant(9\delta'/10)\mu(\mathcal{W}')$;
\item For all $w\in\mathcal{W}'$, we have $\mu(\Gamma_{G'}(w))\geqslant(9\delta'/10)\mu(\mathcal{V}')$;
\item One of the following holds: 
\begin{enumerate}[label=(\roman*)]
\item $q(G')\gg \delta t^{50} q(G)$;
\item $q(G')\gg q(G)$, and if $(v,w)\in\mathcal{E}'$ and we write them as $v=v'\prod_{p\in\mathcal{P}'}p^{f'(p)}$ and $w=w'\prod_{p\in\mathcal{P}'}p^{g'(p)}$, then $L_t(v',w')\geqslant 4$.
\end{enumerate}
\end{enumerate}

Let $\psi:\mathbb{N}\rightarrow\mathbb{R}_{\geqslant 0}$ be a function, and let $\mathcal{A}$ be as in (1.3). Assume, further, that:
\begin{enumerate}
\item For every $q\in\mathbb{Z}$, either $\psi(q)=0$ or $\psi(q)\geqslant 1/2$;
\item $\sum_{q=1}^\infty \psi(q)\varphi(q)/q=\infty$.
\end{enumerate}
Then $\lambda(\mathcal{A})=1$.

Let $G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$. Then there is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P},f,g)$ of $G$ with edge density $\delta'>0$ such that:
\begin{enumerate}
\item $q(G')\geqslant q(G)$;
\item $\delta'\geqslant \delta$;
\item For all $v\in\mathcal{V}'$ and for all $w\in\mathcal{W}'$, we have
\[
\mu(\Gamma_{G'}(v))\geqslant\frac{9\delta'}{10}\mu(\mathcal{W}')
\quad\text{and}\quad \mu(\Gamma_{G'}(w))\geqslant\frac{9\delta'}{10}\mu(\mathcal{V}').
\]
\end{enumerate}

Let	$G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$, and let $\eta\in(0,1)$. Then there is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P},f,g)$ of $G$ with edge density $\delta'>0$ such that both of the following hold:
		\begin{enumerate}
			\item$q(G')\geqslant q(G)>0$.
			\item For all sets $\mathcal{A}\subseteq\mathcal{V}'$ and $\mathcal{B}\subseteq\mathcal{W}'$ such that $\mu(\mathcal{A})\leqslant \eta\cdot \mu(\mathcal{V}')$ and $\mu(\mathcal{B})\leqslant \eta\cdot \mu(\mathcal{W}')$, we have $\mu(\mathcal{E}'\cap(\mathcal{A}\times\mathcal{B}))\leqslant \eta^{9/5}\mu(\mathcal{E}')$.
		\end{enumerate}

Let	$G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$ and let $\eta\in(0,1)$. Then one of the following holds:
\begin{enumerate}
	\item For all sets $\mathcal{A}\subseteq\mathcal{V}$ and $\mathcal{B}\subseteq\mathcal{W}$ such that $\mu(\mathcal{A})\leqslant \eta\cdot  \mu(\mathcal{V})$ and  $\mu(\mathcal{B})\leqslant\eta \cdot \mu(\mathcal{W})$, we have $\mu(\mathcal{E}\cap(\mathcal{A}\times\mathcal{B}))\leqslant \eta^{9/5}\cdot \mu(\mathcal{E})$.
	\item There is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P},f,g)$ of $G$ such that $q(G')>q(G)$,  $\mathcal{V}'\subsetneq \mathcal{V}$ and $\mathcal{W}'\subsetneq \mathcal{W}$.
\end{enumerate}
